CREATE OR REPLACE FUNCTION public.admin_mark_commission(p_offer uuid, p_status text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if not public.is_admin() then raise exception 'admin_only'; end if;
  if p_status not in ('due','paid','waived') then return 'invalid'; end if;
  update public.commissions set status = p_status, paid_at = case when p_status = 'paid' then now() else null end, updated_at = now()
   where offer_id = p_offer;
  get diagnostics n = row_count;
  return case when n > 0 then 'ok' else 'not_found' end;
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_agent(p_user uuid, p_approve boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r text;
begin
  if not public.is_admin() then raise exception 'admin_only'; end if;
  select role into r from public.profiles where id=p_user;
  if not found then return 'no_profile'; end if;
  if r='admin' then return 'is_admin'; end if;
  if p_approve then
    update public.profiles set role='agent', agent_status='approved', agent_verified_at=now() where id=p_user;
  else
    update public.profiles set role='user', agent_status='rejected', agent_verified_at=null where id=p_user;
  end if;
  return 'ok';
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_commission(p_offer uuid, p_seller_type text, p_seller_name text, p_seller_phone text, p_rate numeric)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o record; amt numeric; cur text;
begin
  if not public.is_admin() then raise exception 'admin_only'; end if;
  if p_seller_type not in ('owner','agent','builder') then return 'invalid'; end if;
  if p_rate is null or p_rate < 0 or p_rate > 100 then return 'invalid'; end if;
  select off.id, off.amount, off.listing_id into o
    from public.offers off
    join public.listings l on l.id = off.listing_id
    left join public.profiles p on p.id = l.owner_id
   where off.id = p_offer and off.status = 'accepted' and (l.owner_id is null or p.role = 'admin');
  if not found then return 'not_allowed'; end if;
  select status into cur from public.commissions where offer_id = p_offer;
  if cur = 'paid' then return 'already_paid'; end if;
  amt := round(o.amount * p_rate / 100);
  insert into public.commissions(offer_id, listing_id, seller_type, seller_name, seller_phone, rate, amount, status)
  values (p_offer, o.listing_id, p_seller_type, nullif(trim(coalesce(p_seller_name,'')),''), nullif(trim(coalesce(p_seller_phone,'')),''), p_rate, amt, 'due')
  on conflict (offer_id) do update set seller_type = excluded.seller_type, seller_name = excluded.seller_name,
    seller_phone = excluded.seller_phone, rate = excluded.rate, amount = excluded.amount, status = 'due', paid_at = null, updated_at = now();
  return 'ok';
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_plan(p_email text, p_days integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare uid uuid; n int;
begin
  -- Yeh raha check jo function ke andar bilkul theek kaam karega:
  if not public.is_admin() then 
      raise exception 'admin_only'; 
  end if;

  select id into uid from auth.users where lower(email)=lower(trim(p_email));
  if uid is null then return 'not_found'; end if;
  
  update public.profiles 
  set plan = case when p_days>0 then 'paid' else 'free' end,
      plan_expires_at = case when p_days>0 then now()+make_interval(days=>p_days) else null end 
  where id = uid;
  
  get diagnostics n = row_count;
  return case when n>0 then 'ok' else 'no_profile' end;
end $function$

CREATE OR REPLACE FUNCTION public.guard_listing_featured()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.is_featured and new.kind <> 'property' then
    raise exception 'featured_requires_property';
  end if;

  if tg_op = 'INSERT' then
    if new.is_featured and not public.is_admin() then
      raise exception 'admin_only';
    end if;
  elsif new.is_featured is distinct from old.is_featured
    and not public.is_admin() then
    raise exception 'admin_only';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_agent(p_name text, p_phone text, p_company text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r text;
begin
  if auth.uid() is null then raise exception 'login_required'; end if;
  select role into r from public.profiles where id=auth.uid();
  if not found then return 'no_profile'; end if;
  if r in ('admin','agent') then return 'already'; end if;
  if length(trim(coalesce(p_name,'')))<2 or length(trim(coalesce(p_phone,'')))<7 then return 'invalid'; end if;
  update public.profiles set agent_status='pending', agent_name=trim(p_name), agent_phone=trim(p_phone),
         agent_company=nullif(trim(coalesce(p_company,'')),'') where id=auth.uid();
  return 'ok';
end $function$

CREATE OR REPLACE FUNCTION public.set_listing_agent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r text; s text; n text;
begin
  if new.owner_id is null then return new; end if;
  select role, agent_status, agent_name into r, s, n from public.profiles where id=new.owner_id;
  if not found then new.agent_name:=null; new.agent_verified:=false; return new; end if;
  if r='admin' then new.agent_name:='SAIR Construction'; new.agent_verified:=true;
  elsif r='agent' and s='approved' then new.agent_name:=n; new.agent_verified:=true;
  else new.agent_name:=null; new.agent_verified:=false; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.unlock_contact(p_listing uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ph text; wa text;
begin
  if auth.uid() is null then raise exception 'login_required'; end if;
  if not (public.is_admin() or public.is_paid()) then raise exception 'plan_required'; end if;
  select value into ph from public.app_settings where key='sair_phone';
  select value into wa from public.app_settings where key='sair_whatsapp';
  return json_build_object('phone',ph,'whatsapp',wa);
end $function$
